// SPDX-License-Identifier: AGPL-3.0-only
// Generates typed accessors for BOTH languages from the source-locale catalog:
//   ts/messages.gen.ts  — MessageArgs map used by ts/translator.ts
//   messages_gen.go     — one method per message on *Localizer
//
//   bun run ts/gen.ts
//
// One generator (and one ICU parser) for both outputs keeps the two type
// surfaces identical. Generated files are committed, so `go build` never needs Bun.
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { loadCatalog, root } from "./catalog";
import { type ArgType, extractArgs, parseMessage } from "./icu";

const SOURCE = "en";
const catalog = loadCatalog();

type Msg = { ns: string; key: string; source: string; args: [string, ArgType][] };
const messages: Msg[] = [];
for (const [ns, entries] of Object.entries(catalog[SOURCE]).sort()) {
  for (const [key, entry] of Object.entries(entries).sort()) {
    const args = [...extractArgs(parseMessage(entry.defaultMessage))].sort(([a], [b]) => a.localeCompare(b));
    messages.push({ ns, key, source: entry.defaultMessage, args });
  }
}

// ---- TypeScript ----
const tsType = (t: ArgType): string => {
  switch (t.kind) {
    case "string":
      return "string";
    case "number":
      return "number";
    case "date":
      return "Date | number";
    case "select":
      // Literal options for autocompletion; `other` accepts any string.
      return [...t.options.map((o) => JSON.stringify(o)), "(string & {})"].join(" | ");
    case "tag":
      return "(chunks: string[]) => string";
  }
};
const ts = [
  "// SPDX-License-Identifier: AGPL-3.0-only",
  "// Code generated by ts/gen.ts; DO NOT EDIT.",
  "",
  "export interface MessageArgs {",
  ...messages.map(({ ns, key, source, args }) =>
    [
      `  /** ${source.replaceAll("*/", "*\\/")} */`,
      `  ${JSON.stringify(`${ns}:${key}`)}: { ${args.map(([n, t]) => `${n}: ${tsType(t)}`).join("; ")} };`,
    ].join("\n"),
  ),
  "}",
  "",
  "export type MessageKey = keyof MessageArgs;",
  "",
].join("\n");
writeFileSync(join(root, "ts", "messages.gen.ts"), ts);

// ---- Go ----
const pascal = (s: string) =>
  s
    .split(/[._\-:]/)
    .filter(Boolean)
    .map((p) => p[0].toUpperCase() + p.slice(1))
    .join("");
const camel = (s: string) => {
  const p = pascal(s);
  return p[0].toLowerCase() + p.slice(1);
};
const goType = (t: ArgType): string => {
  switch (t.kind) {
    case "string":
    case "select":
      return "string";
    case "number":
      return t.integer ? "int" : "float64";
    case "date":
      return "time.Time";
    case "tag":
      return "func(string) string";
  }
};
const needsTime = messages.some((m) => m.args.some(([, t]) => t.kind === "date"));
const go = [
  "// SPDX-License-Identifier: AGPL-3.0-only",
  "",
  "// Code generated by ts/gen.ts; DO NOT EDIT.",
  "",
  "package i18nspike",
  "",
  ...(needsTime ? ['import "time"', ""] : []),
  ...messages.flatMap(({ ns, key, source, args }) => {
    const name = pascal(ns) + pascal(key);
    const params = args.map(([n, t]) => `${camel(n)} ${goType(t)}`).join(", ");
    const values = args.length ? `map[string]any{${args.map(([n]) => `${JSON.stringify(n)}: ${camel(n)}`).join(", ")}}` : "nil";
    return [
      `// ${name} formats ${JSON.stringify(`${ns}:${key}`)}.`,
      `//`,
      `//\t${SOURCE}: ${source}`,
      `func (l *Localizer) ${name}(${params}) string {`,
      `\treturn l.Format(${JSON.stringify(`${ns}:${key}`)}, ${values})`,
      "}",
      "",
    ];
  }),
].join("\n");
writeFileSync(join(root, "messages_gen.go"), go);
console.log(`generated ${messages.length} accessors: ts/messages.gen.ts, messages_gen.go`);
